Readings: 0 = no line, 1 = on the left, 2 = in the middle, 3 = on the right. When there is no line, 'B' (gap) is printed if sonYon == 0, otherwise 'A' (search); if there is a line, 'I' (follow). What does this code print?

```
int sonYon = 0;
int okuma[] = {2, 1, 0, 0, 3};

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < 5; i++) {
    int o = okuma[i];
    if (o == 0) {
      Serial.print(sonYon == 0 ? 'B' : 'A');
    } else {
      sonYon = (o == 1) ? -1 : (o == 3) ? 1 : 0;
      Serial.print('I');
    }
  }
  Serial.println();
}
void loop() {}
```

